{
  "root": "main",
  "state": {
    "itinerary": [
      { "dayDate": "Apr 10", "area": "Central Kyoto", "morningActivity": "Arrival, check-in", "afternoonActivity": "Nishiki Market", "dinnerSuggestion": "Pontocho walk", "estCost": "$210", "rainBackup": "Kyoto Railway Museum" },
      { "dayDate": "Apr 11", "area": "Arashiyama", "morningActivity": "Bamboo Grove", "afternoonActivity": "Tenryu-ji gardens", "dinnerSuggestion": "Central Kyoto", "estCost": "$245", "rainBackup": "Kyoto Art Center" },
      { "dayDate": "Apr 12", "area": "Heian Area", "morningActivity": "KYOCERA Museum", "afternoonActivity": "Heian Shrine", "dinnerSuggestion": "Karasuma/Kawaramachi", "estCost": "$190", "rainBackup": "Kyoto National Museum" },
      { "dayDate": "Apr 13", "area": "Nara", "morningActivity": "Todai-ji", "afternoonActivity": "Nara Park", "dinnerSuggestion": "Simple dinner", "estCost": "$220", "rainBackup": "Naramachi museums" },
      { "dayDate": "Apr 14", "area": "Fushimi Inari", "morningActivity": "Fushimi Inari Taisha", "afternoonActivity": "Tofuku-ji/Shopping", "dinnerSuggestion": "Departure meal", "estCost": "$185", "rainBackup": "Manga Museum" }
    ]
  },
  "elements": {
    "main": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md", "padding": 16 },
      "children": ["title", "itineraryTable", "budgetSection", "actions"]
    },
    "title": { "type": "Text", "props": { "text": "Kyoto Spring Trip Snapshot", "variant": "h1" }, "children": [] },
    "itineraryTable": {
      "type": "Table",
      "props": {
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "dayDate",
        "highlightColumns": ["area"],
        "statePath": "/itinerary",
        "columns": [
          { "key": "dayDate", "label": "Day" },
          { "key": "area", "label": "Area" },
          { "key": "morningActivity", "label": "Morning" },
          { "key": "afternoonActivity", "label": "Afternoon" },
          { "key": "estCost", "label": "Cost" },
          { "key": "rainBackup", "label": "Rain Backup" }
        ]
      },
      "children": []
    },
    "budgetSection": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["budgetTitle", "budgetBody"]
    },
    "budgetTitle": { "type": "Text", "props": { "text": "Budget Fit for 2 Adults", "variant": "h2" }, "children": [] },
    "budgetBody": { "type": "Text", "props": { "text": "Estimated total: $1,425–$2,000. This stays comfortably under the $2,400 cap." }, "children": [] },
    "actions": {
      "type": "Stack",
      "props": { "direction": "horizontal", "gap": "sm" },
      "children": ["btn1", "btn2", "btn3"]
    },
    "btn1": { "type": "Button", "props": { "label": "Search hotels", "openUrl": "https://www.booking.com/city/jp/kyoto.html" }, "children": [] },
    "btn2": { "type": "Button", "props": { "label": "Check trains", "openUrl": "https://www.jorudan.co.jp/english/" }, "children": [] },
    "btn3": { "type": "Button", "props": { "label": "Transit map", "openUrl": "https://www2.city.kyoto.lg.jp/kotsu/webguide/en/" }, "children": [] }
  }
}
